mapper.update:
UPDATE crm_whatsapp_message
SET status = #{status}
WHERE tenant_id = #{tenantId} AND message_id = #{messageId}

mapper.select:
SELECT id, tenant_id, conversation_id, wa_id, message_id, message_type,
       content, direction, send_time, status,
       media_id, media_url, media_mime_type, filename, raw_json, source,
       create_time
FROM crm_whatsapp_message
WHERE conversation_id = #{conversationId}

    AND id < #{beforeMsgId}

ORDER BY send_time DESC, id DESC
LIMIT #{pageSize}

mapper.update:
UPDATE crm_whatsapp_message
SET media_url = #{mediaUrl}
WHERE tenant_id = #{tenantId} AND id = #{id}

mapper.select:
SELECT COUNT(1)
FROM crm_whatsapp_message m

    INNER JOIN crm_whatsapp_conversation c ON c.id = m.conversation_id

WHERE m.tenant_id = #{tenantId}
  AND m.direction = 1
  AND m.message_type = 'template'

      AND m.send_time >= #{startTime}


      AND m.send_time <= #{endTime}


      AND c.phone_number_id = #{phoneNumberId}


      AND LOWER(m.status) IN

          LOWER(#{s})

SELECT COUNT(DISTINCT m.conversation_id)
FROM crm_whatsapp_message m

    INNER JOIN crm_whatsapp_conversation c ON c.id = m.conversation_id

WHERE m.tenant_id = #{tenantId}
  AND m.direction = 1
  AND m.message_type = 'template'
  AND m.conversation_id IS NOT NULL

      AND m.send_time >= #{startTime}


      AND m.send_time <= #{endTime}


      AND c.phone_number_id = #{phoneNumberId}

SELECT COUNT(DISTINCT t.conversation_id)
FROM crm_whatsapp_message t

    INNER JOIN crm_whatsapp_conversation c ON c.id = t.conversation_id

WHERE t.tenant_id = #{tenantId}
  AND t.direction = 1
  AND t.message_type = 'template'
  AND t.conversation_id IS NOT NULL

      AND t.send_time >= #{startTime}


      AND t.send_time <= #{endTime}


      AND c.phone_number_id = #{phoneNumberId}

  AND EXISTS (
      SELECT 1 FROM crm_whatsapp_message r
      WHERE r.tenant_id = t.tenant_id
        AND r.conversation_id = t.conversation_id
        AND r.direction = 0
        AND r.send_time >= t.send_time
        AND r.send_time <= t.send_time + #{replyWindowMs}
  )

SELECT COUNT(1)
FROM crm_whatsapp_message
WHERE tenant_id = #{tenantId}
  AND wa_id = #{waId}
  AND direction = 0

SELECT to_char(to_timestamp(m.send_time / 1000.0), 'YYYY-MM-DD') AS date, COUNT(1) FILTER ( WHERE LOWER(m.status) IN ('sent', 'delivered', 'read') ) AS sent, COUNT(1) FILTER ( WHERE LOWER(m.status) IN ('delivered', 'read') ) AS delivered, COUNT(1) FILTER ( WHERE LOWER(m.status) = 'read' ) AS read, COUNT(DISTINCT m.conversation_id) FILTER ( WHERE m.conversation_id IS NOT NULL AND LOWER(m.status) IN ('sent', 'delivered', 'read') ) AS template_conv, COUNT(DISTINCT m.conversation_id) FILTER ( WHERE m.conversation_id IS NOT NULL AND LOWER(m.status) IN ('sent', 'delivered', 'read') AND EXISTS ( SELECT 1 FROM crm_whatsapp_message r WHERE r.tenant_id = m.tenant_id AND r.conversation_id = m.conversation_id AND r.direction = 0 AND r.send_time >= m.send_time AND r.send_time <= m.send_time + #{replyWindowMs} ) ) AS template_conv_replied FROM crm_whatsapp_message m
INNER JOIN crm_whatsapp_conversation c ON c.id = m.conversation_id
WHERE m.tenant_id = #{tenantId} AND m.direction = 1 AND m.message_type = 'template' AND m.send_time IS NOT NULL
AND m.send_time >= #{startTime}
AND m.send_time <= #{endTime}
AND c.phone_number_id = #{phoneNumberId}
GROUP BY to_char(to_timestamp(m.send_time / 1000.0), 'YYYY-MM-DD') ORDER BY date ASC
